-- ═════════════════════════════════════════════════════════════════════════════
-- §A. ROW-LEVEL SECURITY
-- ═════════════════════════════════════════════════════════════════════════════
DO $$
DECLARE
  r record; v_has_hospital boolean; v_hospital_null boolean; v_has_branch boolean;
  v_using text; v_check text; v_count int := 0;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname IN ('core','mdm','patient','clinical','lab','rad','pharmacy','inventory','finance','queue','engage','billing','integration')
      AND c.relkind IN ('r','p') AND c.relispartition = false
      AND c.relname NOT LIKE '\_prisma%' AND c.relname <> 'cdss_safety_floor'
      AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = c.oid AND p.polname = 'tenant_isolation')
    ORDER BY n.nspname, c.relname
  LOOP
    SELECT count(*) FILTER (WHERE column_name='hospital_id') > 0,
           bool_or(column_name='hospital_id' AND is_nullable='YES'),
           count(*) FILTER (WHERE column_name='branch_id') > 0
      INTO v_has_hospital, v_hospital_null, v_has_branch
      FROM information_schema.columns
     WHERE table_schema = r.schema_name AND table_name = r.table_name;

    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.schema_name, r.table_name);

    IF v_has_hospital AND NOT v_hospital_null THEN
      v_using := 'hospital_id = ANY (core.accessible_hospital_ids())';
      IF v_has_branch THEN v_using := v_using || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))'; END IF;
      v_check := v_using;
    ELSIF v_has_hospital AND v_hospital_null THEN
      v_using := '(hospital_id IS NULL OR hospital_id = ANY (core.accessible_hospital_ids()))';
      IF v_has_branch THEN v_using := v_using || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))'; END IF;
      v_check := 'hospital_id = ANY (core.accessible_hospital_ids())';
      IF v_has_branch THEN v_check := v_check || ' AND (branch_id IS NULL OR branch_id = ANY (core.current_branch_ids()))'; END IF;
    ELSE
      v_using := 'false'; v_check := 'false';
    END IF;

    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I.%I', r.schema_name, r.table_name);
    EXECUTE format('CREATE POLICY tenant_isolation ON %I.%I FOR ALL TO hms_app USING (%s) WITH CHECK (%s)', r.schema_name, r.table_name, v_using, v_check);
    EXECUTE format('DROP POLICY IF EXISTS tenant_isolation_ro ON %I.%I', r.schema_name, r.table_name);
    EXECUTE format('CREATE POLICY tenant_isolation_ro ON %I.%I FOR SELECT TO hms_readonly USING (%s)', r.schema_name, r.table_name, v_using);
    v_count := v_count + 1;
  END LOOP;
  RAISE NOTICE 'RLS enabled on % new table(s)', v_count;
END $$;

DO $$
DECLARE v_missing text;
BEGIN
  SELECT string_agg(format('%I.%I', n.nspname, c.relname), ', ') INTO v_missing
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'billing' AND c.relkind IN ('r','p') AND c.relispartition = false
    AND (NOT c.relrowsecurity OR NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid=c.oid AND p.polname='tenant_isolation'));
  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'OP-005 tables without RLS or a tenant policy: %', v_missing;
  END IF;
END $$;


-- ═════════════════════════════════════════════════════════════════════════════
-- §B. THE CONSTRAINTS OP-005 §5 DEPENDS ON
-- ═════════════════════════════════════════════════════════════════════════════

-- ── B.1  one master bill per OP visit ───────────────────────────────────────
--
-- OP-005 §5: "One master bill per OP visit." A second bill for one visit splits
-- a patient's money across two documents that nobody reconciles, and the patient
-- finds out at the counter. Partial, because cancelled and void bills legitimately
-- coexist with the replacement that supersedes them.
CREATE UNIQUE INDEX "uq_bills_one_per_visit"
  ON "billing"."bills" ("hospital_id", "visit_id")
  WHERE "visit_id" IS NOT NULL AND status NOT IN ('cancelled', 'void');

COMMENT ON INDEX "billing"."uq_bills_one_per_visit" IS
  'OP-005 §5: one master bill per OP visit. Cancelled and void bills are excluded so a corrected bill can replace one.';

-- ── B.2  ONE CHARGE, ONE BILL LINE, ONCE ────────────────────────────────────
--
-- `phase-05 §Constraints`, verbatim: "Charge intents carry an idempotency key
-- from the source event; a replayed event must never double-bill. Write the test
-- first." Exit gate 2 replays every charge event three times and expects the
-- bill unchanged. Prisma emitted this as `bill_items_bill_id_source_module_source_ref_id_key`;
-- the comment is what makes it survive a future refactor.
COMMENT ON INDEX "billing"."bill_items_bill_id_source_module_source_ref_id_key" IS
  'phase-05 exit gate 2. A replayed charge event conflicts here instead of adding a second line. This index IS the idempotency guarantee.';

-- ── B.3  Σ bill lines = bill total ──────────────────────────────────────────
--
-- Exit gate 10 asks for it. A report that checks it is a report somebody runs;
-- a trigger makes it something that cannot be false. Deferred to statement end
-- so a service may write the header and the lines in either order within one
-- transaction, which is the normal shape of "post these six charges".
CREATE OR REPLACE FUNCTION "billing".assert_bill_totals()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_bill_id uuid;
  v_lines numeric(14,2);
  v_header numeric(14,2);
  v_status "billing"."BillStatus";
BEGIN
  v_bill_id := COALESCE(NEW.id, OLD.id);

  SELECT status, net_amount INTO v_status, v_header
    FROM "billing"."bills" WHERE id = v_bill_id;

  -- A draft is mid-assembly by definition; only a presented bill must balance.
  IF v_status IS NULL OR v_status = 'draft' THEN RETURN NULL; END IF;

  SELECT COALESCE(sum(net), 0) INTO v_lines
    FROM "billing"."bill_items"
   WHERE bill_id = v_bill_id AND status <> 'cancelled';

  -- The round-off is a real rupee under Section 170, so it is part of the
  -- header and must be allowed for when comparing against the lines.
  IF abs((v_lines + COALESCE((SELECT round_off FROM "billing"."bills" WHERE id = v_bill_id), 0)) - v_header) > 0.01 THEN
    RAISE EXCEPTION
      'Bill % does not balance: lines total %, header says % (OP-005 §5, phase-05 exit gate 10).',
      v_bill_id, v_lines, v_header
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER "bills_must_balance"
  AFTER INSERT OR UPDATE ON "billing"."bills"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "billing".assert_bill_totals();

-- ── B.4  a finalised bill is immutable ──────────────────────────────────────
--
-- OP-005 §5: "finalized invoices/receipts immutable; corrections through
-- credit/debit notes". The status may still advance as money arrives — that is
-- what `partially_paid` and `paid` are — but the amounts may not move.
CREATE OR REPLACE FUNCTION "billing".refuse_finalized_bill_edit()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.status IN ('finalized', 'partially_paid', 'paid', 'cancelled', 'void') THEN
    IF NEW.gross_amount    IS DISTINCT FROM OLD.gross_amount
    OR NEW.discount_amount IS DISTINCT FROM OLD.discount_amount
    OR NEW.taxable_amount  IS DISTINCT FROM OLD.taxable_amount
    OR NEW.cgst            IS DISTINCT FROM OLD.cgst
    OR NEW.sgst            IS DISTINCT FROM OLD.sgst
    OR NEW.igst            IS DISTINCT FROM OLD.igst
    OR NEW.net_amount      IS DISTINCT FROM OLD.net_amount THEN
      RAISE EXCEPTION
        'Bill % is % and its amounts are immutable. Raise a credit note (OP-005 §5).',
        OLD.id, OLD.status
        USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER "bills_immutable_when_finalized"
  BEFORE UPDATE ON "billing"."bills"
  FOR EACH ROW EXECUTE FUNCTION "billing".refuse_finalized_bill_edit();

-- A line on a finalised bill cannot move at all.
CREATE OR REPLACE FUNCTION "billing".refuse_finalized_item_edit()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_status "billing"."BillStatus";
BEGIN
  SELECT status INTO v_status FROM "billing"."bills"
   WHERE id = COALESCE(NEW.bill_id, OLD.bill_id);
  IF v_status IN ('finalized', 'partially_paid', 'paid') THEN
    RAISE EXCEPTION
      'Bill % is finalised; its lines are immutable. Raise a credit note (OP-005 §5).',
      COALESCE(NEW.bill_id, OLD.bill_id)
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;

CREATE TRIGGER "bill_items_immutable_when_finalized"
  BEFORE INSERT OR UPDATE OR DELETE ON "billing"."bill_items"
  FOR EACH ROW EXECUTE FUNCTION "billing".refuse_finalized_item_edit();

-- ── B.5  GST is either intra-state or inter-state, never both ───────────────
--
-- OP-005 §5: "intra-state → CGST+SGST split equally; inter-state → IGST". A row
-- carrying both is a return that will not file, and the two halves of an
-- intra-state split are equal by law rather than by convention.
ALTER TABLE "billing"."bill_items"
  ADD CONSTRAINT "bill_items_gst_mutually_exclusive"
  CHECK (("igst" = 0) OR ("cgst" = 0 AND "sgst" = 0));

ALTER TABLE "billing"."bill_items"
  ADD CONSTRAINT "bill_items_cgst_equals_sgst"
  CHECK ("cgst" = "sgst");

-- An exempt line carries no tax at all; a taxable one is not exempt.
ALTER TABLE "billing"."bill_items"
  ADD CONSTRAINT "bill_items_exempt_carries_no_tax"
  CHECK (NOT "is_exempt" OR ("cgst" = 0 AND "sgst" = 0 AND "igst" = 0 AND "cess" = 0));

ALTER TABLE "billing"."bill_items"
  ADD CONSTRAINT "bill_items_amounts_non_negative"
  CHECK ("gross" >= 0 AND "discount_amount" >= 0 AND "taxable_value" >= 0 AND "net" >= 0);

-- A discount cannot exceed what is being discounted.
ALTER TABLE "billing"."bill_items"
  ADD CONSTRAINT "bill_items_discount_within_gross"
  CHECK ("discount_amount" <= "gross");

ALTER TABLE "billing"."bills"
  ADD CONSTRAINT "bills_amounts_non_negative"
  CHECK ("gross_amount" >= 0 AND "net_amount" >= 0 AND "paid_amount" >= 0);

-- ── B.6  requester ≠ approver, on every discount ────────────────────────────
--
-- OP-005 §5: "approval matrix mandatory; reason codes; requester ≠ approver".
-- The permission split alone would let one person hold both keys; this refuses
-- the specific person, which is the half a role matrix cannot express.
ALTER TABLE "billing"."discount_requests"
  ADD CONSTRAINT "discount_requests_maker_is_not_checker"
  CHECK ("approved_by" IS NULL OR "approved_by" <> "requested_by");

ALTER TABLE "billing"."discount_requests"
  ADD CONSTRAINT "discount_requests_decided_has_approver"
  CHECK (status = 'pending' OR status = 'withdrawn' OR ("decided_at" IS NOT NULL AND "approved_by" IS NOT NULL));

-- ── B.7  a credit note must point at what it reverses ───────────────────────
ALTER TABLE "billing"."invoices"
  ADD CONSTRAINT "invoices_credit_note_references_original"
  CHECK ("doc_type" NOT IN ('credit_note', 'debit_note') OR "original_invoice_id" IS NOT NULL);

-- A B2B invoice needs the recipient's GSTIN, or it is not a B2B invoice.
ALTER TABLE "billing"."invoices"
  ADD CONSTRAINT "invoices_b2b_needs_gstin"
  CHECK (NOT "is_b2b" OR "recipient_gstin" IS NOT NULL);


-- ═════════════════════════════════════════════════════════════════════════════
-- §C. GRANTS, AND "NEVER HARD-DELETED" MADE TRUE
-- ═════════════════════════════════════════════════════════════════════════════
DO $$
DECLARE r record; v_count int := 0;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name, c.oid
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'billing' AND c.relkind IN ('r','p') AND c.relispartition = false
      AND c.relname NOT LIKE '\_prisma%'
      AND NOT has_table_privilege('hms_app', c.oid, 'SELECT')
  LOOP
    EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON %I.%I TO hms_app', r.schema_name, r.table_name);
    EXECUTE format('GRANT SELECT ON %I.%I TO hms_readonly', r.schema_name, r.table_name);
    v_count := v_count + 1;
  END LOOP;
  RAISE NOTICE 'Granted application DML on % OP-005 table(s)', v_count;
END $$;

-- `CLAUDE.md §4`: "Soft delete only where legally allowed; clinical & financial
-- rows are never hard-deleted." These four are the financial record. A bill is
-- cancelled, an invoice is credit-noted, a line is marked cancelled — and all of
-- them stay, because the register has to add up to what was issued rather than
-- to what survived.
REVOKE DELETE ON "billing"."bills"             FROM hms_app;
REVOKE DELETE ON "billing"."bill_items"        FROM hms_app;
REVOKE DELETE ON "billing"."invoices"          FROM hms_app;
REVOKE DELETE ON "billing"."discount_requests" FROM hms_app;

COMMENT ON TABLE "billing"."bills" IS
  'The master bill. Never deleted: cancellation is a status and the row stays, because a register that only holds surviving bills does not reconcile to what was issued (CLAUDE.md §4, OP-005 §5).';

COMMENT ON TABLE "billing"."invoices" IS
  'GST documents, gapless per series per financial year. A cancelled invoice keeps its number and appears in the register as cancelled — a reused number is a return that will not file.';

COMMENT ON TABLE "billing"."bill_items" IS
  'Bill lines, idempotent on (bill_id, source_module, source_ref_id). That index is phase-05 exit gate 2: replay a charge event three times and the bill is unchanged.';
